import{calculator,CalcError,bool,has,num,pos,nonneg,dflt}from './core.js?ver=467cb2c42a';import{fmt}from './format.js?ver=467cb2c42a';function tariffOf(d){const t=d?.tariff;if(!t?.unprotected?.length||!t?.protected?.length)throw new CalcError('tariff_data_missing','tariff');return t;}
