const SIGNED=['qta_rs','fpa_rs','qta_per_unit','fpa_per_unit'];
export const bill_tou=calculator((i,d)=>{const t=tariffOf(d).tou;const peak_units=nonneg(i,'peak_units');const offpeak_units=nonneg(i,'offpeak_units');const sanctioned_kw=pos(i,'sanctioned_kw');const mdi_kw=nonneg(i,'mdi_kw',0);if(!(t.fixed_min_fraction>0))throw new CalcError('tariff_data_missing','tariff');const billable_kw=Math.max(t.fixed_min_fraction*sanctioned_kw,mdi_kw);const units=peak_units+offpeak_units;const base={units,category:'tou',energy_rs:peak_units*t.peak+offpeak_units*t.offpeak,fixed_rs:t.fixed_per_kw*billable_kw};return{peak_units,offpeak_units,sanctioned_kw,mdi_kw,billable_kw,...addOns(base,i,d),units,category:'tou',energy_calc:`${fmt(peak_units)} × ${fmt(t.peak,'rs2')} + ${fmt(offpeak_units)} × ${fmt(t.offpeak,'rs2')}`};},{allowNegative:SIGNED});function billLines(i,d){const base=bill_energy.raw(i,d);const avg_rate=base.units>0?base.energy_rs/base.units:base.rate;const t=tariffOf(d)[base.category];const parts=[];if(base.category==='protected'){let prev=0;for(let k=0;k<=base.band_index;k++){const top=Math.min(base.units,t[k].upto);if(top>prev||k===base.band_index)parts.push(`${fmt(top-prev)} × ${fmt(t[k].rate,'rs2')}`);prev=top;}}else parts.push(`${fmt(base.units)} × ${fmt(base.rate,'rs2')}`);return{...base,...addOns(base,i,d),avg_rate,energy_calc:parts.join(' + ')};}
